from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent.parent
out=ROOT/'library'
audit=json.loads((out/'part-previews/part-previews.audit.json').read_text())
asm=json.loads((out/'assembly-previews/index.json').read_text())
labels=json.loads((ROOT/'native-cad/component-labels.json').read_text())['by_basename']
by_stem={Path(k).stem.casefold():v for k,v in labels.items()}
rows=[]; groups={}
for r in audit['rows']: groups.setdefault(r['source_id'],[]).append(r)
for sid,views in groups.items():
 r=views[0]; name=r['source_filename']; l=labels.get(name) or by_stem.get(Path(name).stem.casefold()) or {}
 title=l.get('label_zh',name)
 if name.startswith('DRLJG-TANK'):title='贮箱钻模'
 if name.startswith('BRKT-EGSE'):title='地面设备安装支架'
 if name.startswith('CVR-ANT'):title='地面设备接收天线罩'
 rows.append({'id':sid,'name':name,'title':title,'kind':'stl' if 'STL' in r['format'] else 'native','category':l.get('category','原交换文件'),'triangles':r['source_triangles'],'mass_volume':r['source_mass_volume'],'revision':'main-R01','resolution':[768,768],'views':{v['view']:{'image':'part-previews/'+Path(v['image']).name,'sha256':v['image_sha256']} for v in views}})
for r in asm['rows']:
 rows.append({'id':r['id'],'name':r['source_filename'],'title':r['label_zh'],'kind':'patch' if r['id']=='A15' else 'assembly','triangles':r['triangles'],'mass_volume':False,'revision':'HCR-5105 独立修订' if r['id']=='A15' else 'main-R01','resolution':[1280,960],'views':{v['view']:{'image':'assembly-previews/'+v['image'],'sha256':v['image_sha256']} for v in r['renders']}})
assert len(rows)==170 and sum(len(r['views']) for r in rows)==510
text='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>启明火箭 · 170条原件图册</title><style>
*{box-sizing:border-box}body{margin:0;background:#edece6;color:#252922;font:14px/1.7 -apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft Yahei',sans-serif}header,main{max-width:1500px;margin:auto;padding:30px 28px}header{padding-bottom:0}small,.note{color:#6e7469}h1{font:38px/1.3 Georgia,'Songti SC',serif;margin:12px 0}.toolbar{display:flex;gap:12px;position:sticky;top:0;z-index:2;background:#edece6ed;padding:15px 0;backdrop-filter:blur(6px)}input,select,button{font:inherit;padding:9px;border:1px solid #cbcfc4;border-radius:5px;background:#fafbf7;color:inherit}input{width:100%;max-width:650px}button{cursor:pointer}.count{margin:8px 0 22px;color:#69735e}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:20px}.card{border:1px solid #cdd1c5;background:#f9faf5;border-radius:7px;overflow:hidden}.picture{display:block;border:0;padding:0;background:#29343a;width:100%;cursor:zoom-in}.picture img{width:100%;aspect-ratio:1;object-fit:contain;display:block}.info{padding:14px}.info b{display:block;font-size:16px;font-weight:500}.filename{font:10px/1.6 ui-monospace,monospace;word-break:break-word;color:#73816d;margin-top:8px}.tag{font-size:10px;letter-spacing:.04em;color:#78846b}.mass{color:#946e2a}.error{color:#a5262d;background:#fff0ec;padding:8px}.views{display:flex;gap:5px;padding:8px 12px;background:#f1f3eb}.views button{font-size:11px;padding:4px 12px}.views .on{background:#56694d;color:white}.empty{padding:50px}dialog{border:1px solid #bcc5b1;border-radius:8px;background:#f4f5ee;color:inherit;width:min(1100px,96vw);max-height:94vh;padding:20px}dialog::backdrop{background:#101a20bb}dialog header{padding:0;display:flex;justify-content:space-between;gap:15px}dialog h2{font-size:20px;font-weight:500;margin:0}dialog img{display:block;margin:12px auto;width:100%;height:min(65vh,750px);object-fit:contain;background:#29343a}dialog code{display:block;overflow-wrap:anywhere;white-space:pre-wrap;font-size:10px}a{color:#4a6242}.scope{border-left:3px solid #8a947a;padding-left:15px;margin-top:15px;font-size:12px}@media(max-width:600px){header,main{padding:20px 15px}h1{font-size:27px}.toolbar{flex-wrap:wrap;gap:6px}.toolbar input{flex:1;min-width:180px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.info{padding:10px}.info b{font-size:12px}.filename{font-size:8px}.tag{font-size:8px}.views{padding:5px;gap:3px}.views button{padding:4px 7px}dialog img{height:50vh}}
</style><header><small>HALF CAT ROCKETRY · 启明火箭 · 源几何图册</small><h1>170条源记录，510张实际图片。</h1><p>119个原生零件文件、36个原STL文件、14个装配文件，以及1个单独标识的HCR-5105修订件。每条都有正视、侧视和斜视图；点图可放大。</p><div class="scope">零件与STL图为768×768，装配与修订件图为1280×960。所有图片均由对应源几何实际渲染；灰色检视材质用于看清形状。薄片保留原始厚度，五种Mass Volume保留原作体积占位。170是源文件记录数，不能视作170种物理零件或与172行BOM逐项等同；修订件未自动并入R01装配。启明火箭为本地展示名；原设计归属Half Cat Rocketry，精确原文件身份保留在来源记录中。</div></header><main><div class="toolbar"><input id="search" type="search" placeholder="搜索中文、显示文件名或编号"><select id="kind"><option value="">全部源记录</option><option value="native">原生CAD零件 · 119</option><option value="stl">原STL格式记录 · 36</option><option value="assembly">原生装配 · 14</option><option value="patch">独立修订件 · 1</option></select></div><div class="count" aria-live="polite"></div><div class="grid"></div></main><dialog><header><h2></h2><button id="close" aria-label="关闭图片">×</button></header><div class="views modal-views"></div><img alt=""><p class="detail"></p><a id="open-image" target="_blank">打开原尺寸图片</a><code></code></dialog><script>
const DATA=__DATA__,NAMES={native:'原生CAD零件',stl:'原STL格式记录',assembly:'原生装配',patch:'独立修订件'},VIEWS={front:'正视',side:'侧视',oblique:'斜视'},state=new Map();const $=s=>document.querySelector(s),esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const displayName=s=>String(s).replace(/Mojave[\\s_-]*Sphinx|MojaveSphinx|\\bSphinx\\b|莫哈韦(?:斯芬克斯)?|莫哈维(?:斯芬克斯)?|莫哈弗(?:斯芬克斯)?|斯芬克斯/gi,'启明火箭');
const buttons=(r,v)=>Object.entries(VIEWS).map(([k,n])=>`<button class="${k===v?'on':''}" data-id="${r.id}" data-view="${k}">${n}</button>`).join('');
function draw(){const q=$('#search').value.toLowerCase(),kind=$('#kind').value,rows=DATA.filter(r=>(!kind||kind===r.kind)&&(!q||(displayName(r.title)+' '+displayName(r.name)+' '+r.name+' '+r.id).toLowerCase().includes(q)));$('.count').textContent=rows.length+' / '+DATA.length+' 条源记录 · 每条3张，共510张';$('.grid').innerHTML=rows.map(r=>{const v=state.get(r.id)||'oblique';return `<article class="card" data-card="${r.id}"><button class="picture" data-id="${r.id}" aria-label="放大${esc(displayName(r.title))}"><img src="${r.views[v].image}" alt="${esc(displayName(r.title))} · ${VIEWS[v]}" loading="lazy"></button><div class="views">${buttons(r,v)}</div><div class="info"><span class="tag">${r.id} · ${NAMES[r.kind]} · ${r.resolution.join('×')}</span><b>${esc(displayName(r.title))}</b>${r.mass_volume?'<span class="tag mass">原作体积占位 · 无布伞展开细节</span>':''}<div class="filename">${esc(displayName(r.name))}</div></div></article>`;}).join('');}
let current=null;function modal(r,v){current=r;state.set(r.id,v);$('dialog h2').textContent=displayName(r.title);$('.modal-views').innerHTML=buttons(r,v);$('dialog img').src=r.views[v].image;$('dialog img').alt=displayName(r.title)+' · '+VIEWS[v];$('dialog .detail').textContent=r.id+' · '+VIEWS[v]+' · '+r.resolution.join('×')+' · '+r.triangles.toLocaleString()+'个源三角面 · '+r.revision+(r.mass_volume?'。原作使用质量/体积占位，本图保留该简化。':'');$('#open-image').href=r.views[v].image;$('dialog code').textContent='展示文件名：'+displayName(r.name)+'\\n图片 SHA256 '+r.views[v].sha256;}
$('.grid').onclick=e=>{const el=e.target.closest('[data-id]');if(!el)return;const r=DATA.find(x=>x.id===el.dataset.id);if(el.dataset.view){state.set(r.id,el.dataset.view);const card=el.closest('.card'),v=el.dataset.view;card.querySelector('img').src=r.views[v].image;card.querySelector('img').alt=displayName(r.title)+' · '+VIEWS[v];card.querySelector('.views').innerHTML=buttons(r,v);return;}modal(r,state.get(r.id)||'oblique');$('dialog').showModal();};$('.modal-views').onclick=e=>{const el=e.target.closest('[data-view]');if(el)modal(current,el.dataset.view);};$('#close').onclick=()=>$('dialog').close();$('#search').oninput=draw;$('#kind').onchange=draw;draw();window.previewData=DATA;window.previewEvidence={sourceRecords:DATA.length,nativeRecords:119,stlRecords:36,assemblyRecords:14,patchRecords:1,allImages:new Set(DATA.flatMap(r=>Object.values(r.views).map(v=>v.image))).size};
</script></html>'''
(out/'逐件原件预览.html').write_text(text.replace('__DATA__',json.dumps(rows,ensure_ascii=False).replace('</','<\\/')))
(out/'preview-index.json').write_text(json.dumps({'records':rows,'source_record_count':len(rows),'image_count':510},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'source_records':len(rows),'images':510},ensure_ascii=False))
